# Code generated by Claude
"""
When the handoff weight reading may be taken (src/weight_estimate.reading_status, WEIGHT_READING_CFG["max_wait_s"], decisions-log M192). No simulation: speeds are made up, one tick per 1/150 s.

    python experiments/weight_reading_timing_test.py

The rule: the arm must be still (every joint under the speed threshold for the whole window) AND within max_wait_s of the handoff; otherwise "no reading", never a reading taken later (the 300 g
pick handoff was once read 5.5 s late, during the place, and gave -16 g).
"""
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from src.task_config import WEIGHT_READING_CFG  # noqa: E402
from src.weight_estimate import reading_status  # noqa: E402

HZ, THR, WIN = 150, 0.005, 0.30
MAXW = WEIGHT_READING_CFG["max_wait_s"]
results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


def run(still_from, trigger=10.0, end=20.0, moving=0.05):
    """Ticks from t=0 to `end`; the arm moves (speed `moving`) until `still_from` and is still (0) after it. Returns (the first status other than 'wait' after the handoff, the time)."""
    speeds = []
    t = 0.0
    k = 0
    while t <= end:
        speeds.append(moving if t < still_from else 0.0)
        t = k / HZ
        k += 1
        if t >= trigger:
            s = reading_status(speeds, trigger, t, THR, WIN, MAXW, HZ)
            if s != "wait":
                return s, t - trigger
    return "wait", None


def main():
    print(f"max_wait_s = {MAXW} s (PENDING David)")
    print("\n1. the arm is already still at the handoff: the reading is taken at once")
    s, w = run(still_from=5.0)
    check("still since 5 s, handoff at 10 s: take, 0 s after the handoff", s == "take" and w is not None and w < 0.02, f"{s} {w}")
    print("\n2. the arm becomes still shortly after the handoff")
    s, w = run(still_from=10.2)
    check("still from 0.2 s after the handoff: take, 0.5 s after it (window 0.3 s)", s == "take" and w is not None and 0.45 <= w <= 0.55 and w <= MAXW, f"{s} {w}")
    print("\n3. the arm becomes still only after the time limit")
    s, w = run(still_from=10.0 + 5.2)
    check("still from 5.2 s after the handoff (the 300 g case): no reading, decided at the limit, not 5.5 s later", s == "no reading" and w is not None and abs(w - MAXW) < 0.02, f"{s} {w}")
    print("\n4. the window is complete only just after the limit")
    s, w = run(still_from=10.0 + MAXW - 0.1)           # window would complete 0.2 s after the limit
    check("window completes after the limit: no reading", s == "no reading", f"{s} {w}")
    s, w = run(still_from=10.0 + MAXW - WIN - 0.02)    # window completes just before the limit
    check("window completes just before the limit: take", s == "take" and w <= MAXW, f"{s} {w}")
    print("\n5. never still")
    s, w = run(still_from=1e9)
    check("never still: no reading at the limit", s == "no reading" and abs(w - MAXW) < 0.02, f"{s} {w}")
    print("\n6. a short still stretch is not enough")
    speeds = [0.05] * 200 + [0.0] * int(0.2 * HZ)         # 0.2 s still, window is 0.3 s
    check("0.2 s of stillness against a 0.3 s window, in time: wait", reading_status(speeds, 0.0, 0.5, THR, WIN, MAXW, HZ) == "wait")
    print("\n7. the speed threshold")
    speeds = [0.0] * 100 + [0.006] + [0.0] * 20
    check("one tick at 0.006 rad/s inside the window: not still", reading_status(speeds, 0.0, 0.2, THR, WIN, MAXW, HZ) != "take")
    print(f"\n{sum(results)}/{len(results)} passed")
    sys.exit(0 if all(results) else 1)


if __name__ == "__main__":
    main()
